result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "tests/test_ingest.py", "content": "import csv
import os
import sqlite3
import subprocess
import sys

import pytest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from ingest import ingest  # noqa: E402

EXPECTED_GOOD = {
    "store_a.csv": 4,
    "store_b.csv": 5,
    "garbage.csv": 3,
}
EXPECTED_BAD = {
    "store_a.csv": {"BAD_INT": 1, "BAD_DATE": 1},
    "store_b.csv": {},
    "garbage.csv": {
        "BAD_COLUMN_COUNT": 3,
        "BAD_INT": 1,
        "BAD_DATE": 1,
    },
}


@pytest.fixture(scope="module")
def result(tmp_path_factory):
    tmp = tmp_path_factory.mktemp("run")
    data_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "data")
    subprocess.run(
        [sys.executable, os.path.join(os.path.dirname(data_dir), "generate_data.py")],
        check=True,
    )
    db = tmp / "shipments.db"
    report = tmp / "rejects_report.txt"
    good, reasons = ingest(data_dir=data_dir, db_path=str(db), report_path=str(report))
    conn = sqlite3.connect(str(db))
    yield tmp, db, report, good, reasons, conn
    conn.close()


def query(result, sql):
    return result[5].execute(sql).fetchall()


def test_exact_good_rows_per_file(result):
    rows = dict(query(result, "SELECT file, COUNT(*) FROM shipments GROUP BY file"))
    for fname, expected in EXPECTED_GOOD.items():
        assert rows.get(fname) == expected, f"{fname}: expected {expected} good rows"


def test_total_good_rows(result):
    (total,) = query(result, "SELECT COUNT(*) FROM shipments")[0]
    assert total == sum(EXPECTED_GOOD.values())  # 12


def test_embedded_newline_row_ingested_not_quarantined(result):
    # The row with sku containing a raw newline inside quotes must land in
    # shipments with the newline preserved.
    hits = query(
        result,
        "SELECT file, line_no, sku, qty FROM shipments WHERE sku LIKE '%\n%'",
    )
    assert len(hits) == 2, "both multi-line skus must be ingested"
    for file, line_no, sku, qty in hits:
        assert "\n" in sku
        assert isinstance(qty, int)
        assert file == "store_b.csv"
        # line_no is the real line number of the LAST physical line of the record
    assert {h[1] for h in hits} == {4, 6}


def test_quarantine_reason_counts_per_file(result):
    rows = query(
        result,
        "SELECT file, reason, COUNT(*) FROM quarantine GROUP BY file, reason",
    )
    actual = {}
    for file, reason, n in rows:
        actual.setdefault(file, {})[reason] = n
    for fname, expected in EXPECTED_BAD.items():
        assert actual.get(fname, {}) == expected


def test_total_quarantine_counts_by_reason(result):
    counts = dict(query(result, "SELECT reason, COUNT(*) FROM quarantine GROUP BY reason"))
    expected_totals = {}
    for reasons in EXPECTED_BAD.values():
        for r, n in reasons.items():
            expected_totals[r] = expected_totals.get(r, 0) + n
    assert counts == expected_totals  # BAD_COLUMN_COUNT:3, BAD_INT:2, BAD_DATE:2


def test_quarantine_has_raw_line_and_valid_reason(result):
    rows = query(result, "SELECT file, line_no, raw_line, reason FROM quarantine")
    valid = {"BAD_COLUMN_COUNT", "BAD_INT", "BAD_DATE"}
    assert rows, "quarantine table must not be empty"
    for file, line_no, raw_line, reason in rows:
        assert reason in valid
        assert isinstance(line_no, int) and line_no >= 2  # header was line 1
        assert isinstance(raw_line, str) and raw_line


def test_report_grouped_by_reason_with_counts(result):
    text = open(result[2], encoding="utf-8").read()
    lines = [l for l in text.splitlines() if ":" in l]
    entries = {}
    for line in lines:
        key, val = line.rsplit(":", 1)
        if key != "TOTAL":
            entries[key.strip()] = int(val)
    assert entries == {"BAD_COLUMN_COUNT": 3, "BAD_INT": 2, "BAD_DATE": 2}
    total = next(int(v) for k, v in (l.rsplit(":", 1) for l in lines) if k == "TOTAL")
    assert total == 7


def test_shipments_qty_is_integer_type(result):
    types = {t for (t,) in query(result, "SELECT typeof(qty) FROM shipments")}
    assert types == {"integer"}


def test_cli_end_to_end(tmp_path):
    repo = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
    out_db = tmp_path / "cli.db"
    out_rep = tmp_path / "cli_report.txt"
    import ingest as mod

    good, reasons = mod.ingest(
        data_dir=os.path.join(repo, "data"),
        db_path=str(out_db),
        report_path=str(out_rep),
    )
    assert good == 12
    assert sum(reasons.values()) == 7
